    qProd (primesLE 3) u - qProd (primesLE M) u ≤ qProd ({3} : Finset Nat) u * u ^ 5

private theorem primeSandwichLowerFun_intervalIntegrable (N m : Nat) :
    IntervalIntegrable (fun u => primeSandwichLowerFun N m u)
      MeasureTheory.volume (0 : ℝ) 1

theorem F_antitone {S T : Finset Nat}
    (hST : S ⊆ T) :
    F T ≤ F S

private lemma exp_lower :
    (1.4262 : ℝ) ≤
      (1 + 193571378 / (10 : ℝ) ^ 16) * downstreamF (exp (20 : ℝ))

private lemma exp_upper :
    (1 + 193571378 / (10 : ℝ) ^ 16) * downstreamF (exp (20 : ℝ)) ≤
      (1.4262 : ℝ) + (1 : ℝ) / 10 ^ 4

private theorem checkedCell_bound (c : Cell) (hc : checkCell c = true) :
    ∀ x ∈ Set.Icc (c.lo : ℝ) c.hi,
      Expr.eval (fun _ => x) lhs ≤ Expr.eval (fun _ => x) (rhs (1 / c.eps))

theorem checkDomainValidAffine_correct {e : Expr} {ρ : AffineEnv} {cfg : AffineConfig}
    (h : checkDomainValidAffine e ρ cfg = true) :
    evalDomainValidAffine e ρ cfg

theorem verify_cubic_distinct_roots_separated (P : QCubic) {eps : ℚ}
    (hcount : P.threeRootCountCheck = true)
    (hmesh : P.separationMeshCheck eps = true) {x y : ℝ}
    (hx : x ∈ Engine.Algebra.cubicZeroSet P.toReal)
    (hy : y ∈ Engine.Algebra.cubicZeroSet P.toReal) (hxy : x ≠ y) :
    (eps : ℝ) < |x - y|

private theorem coverage_tail_contiguous (e : PartitionEntry) (es : List PartitionEntry)
    (domain : IntervalRat) (hcov : checkCoverage (e :: es) domain = true) :
    checkCoverage.checkContiguous domain es e.domain.hi = true

private theorem coverage_first_hi_le (entries : List PartitionEntry) (domain : IntervalRat)
    (hcov : checkCoverage entries domain = true) (hne : entries ≠ []) :
    (entries.head hne).domain.hi ≤ domain.hi

private theorem checkAdjacent_correct (parts : List IntervalRat) :
    checkAdjacent parts = true → ∀ k (hk : k + 1 < parts.length),
      (parts[k]'(by omega)).hi = (parts[k + 1]'hk).lo

private theorem lo_le_part_lo (parts : List IntervalRat) (I : IntervalRat)
    (hcover : ListPartitionCovers parts I) (k : ℕ) (hk : k < parts.length) :
    I.lo ≤ (parts[k]'hk).lo

private theorem part_hi_le_hi (parts : List IntervalRat) (I : IntervalRat)
    (hcover : ListPartitionCovers parts I) (k : ℕ) (hk : k < parts.length) :
    (parts[k]'hk).hi ≤ I.hi
